const controls=document.querySelector('.directory-controls');controls.hidden=false;
const cards=Array.from(document.querySelectorAll('#directory-grid .project-card'));
const search=document.querySelector('#program-search'),statusFilter=document.querySelector('#program-status'),chips=Array.from(document.querySelectorAll('[data-category-filter]'));
const count=document.querySelector('#directory-count'),empty=document.querySelector('#directory-empty');
let category='all';
function readFilters(){const params=new URLSearchParams(location.search);category=params.get('kategori')||'all';if(!chips.some(b=>b.dataset.categoryFilter===category))category='all';search.value=params.get('carian')||'';statusFilter.value=params.get('status')==='planned'?'planned':'all'}
function applyFilters(updateUrl=true){const q=search.value.trim().toLocaleLowerCase('ms');let visible=0;cards.forEach(card=>{const matches=(category==='all'||card.dataset.category===category)&&(statusFilter.value==='all'||card.dataset.planned==='true')&&(card.dataset.search||card.textContent).toLocaleLowerCase('ms').includes(q);card.hidden=!matches;if(matches)visible++});chips.forEach(button=>{const selected=button.dataset.categoryFilter===category;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected))});count.textContent=`${visible} daripada ${cards.length} program & inisiatif`;empty.hidden=visible>0;if(updateUrl){const url=new URL(location.href);[['kategori',category==='all'?'':category],['carian',search.value.trim()],['status',statusFilter.value==='all'?'':statusFilter.value]].forEach(([key,value])=>value?url.searchParams.set(key,value):url.searchParams.delete(key));history.replaceState(null,'',url)}}
chips.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.categoryFilter;applyFilters()}));search.addEventListener('input',()=>applyFilters());statusFilter.addEventListener('change',()=>applyFilters());document.querySelector('#reset-programs').addEventListener('click',()=>{category='all';search.value='';statusFilter.value='all';applyFilters();search.focus()});window.addEventListener('popstate',()=>{readFilters();applyFilters(false)});readFilters();applyFilters(false);
